-- PostgreSQL fresh-install reference. IDs are generated by the application.
-- Execute through a migration runner using a dedicated product database.
BEGIN;

CREATE TABLE workspaces (
  id uuid PRIMARY KEY, name text NOT NULL,
  journal_epoch uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE repositories (
  id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id),
  name text NOT NULL, approved_path text NOT NULL, remote_url text,
  policy jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (workspace_id, name)
);
CREATE TABLE source_plugins (
  id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id),
  plugin_id text NOT NULL, package_version text NOT NULL,
  image_digest text NOT NULL CHECK (image_digest ~ '^sha256:[a-f0-9]{64}$'),
  name text NOT NULL, revision integer NOT NULL CHECK (revision > 0),
  manifest jsonb NOT NULL, config jsonb NOT NULL, grants jsonb NOT NULL,
  secret_refs jsonb NOT NULL DEFAULT '[]', enabled boolean NOT NULL DEFAULT true,
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (workspace_id, name)
);
CREATE TABLE routing_rules (
  id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id),
  revision integer NOT NULL CHECK (revision > 0), enabled boolean NOT NULL DEFAULT true,
  priority integer NOT NULL DEFAULT 0,
  match_kind text NOT NULL CHECK (match_kind IN ('webhook', 'exact', 'prefix', 'regex', 'fallback')),
  pattern text NOT NULL CHECK (length(pattern) <= 2048),
  normalization text NOT NULL DEFAULT 'none' CHECK (normalization IN ('none', 'uppercase', 'lowercase')),
  source_plugin_id uuid NOT NULL REFERENCES source_plugins(id),
  repository_id uuid NOT NULL REFERENCES repositories(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (match_kind <> 'regex' OR length(pattern) <= 512),
  CHECK (match_kind <> 'fallback' OR pattern = '')
);
CREATE INDEX routing_rules_resolution ON routing_rules(workspace_id, enabled, priority DESC);
CREATE TABLE tasks (
  id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id),
  source_plugin_id uuid NOT NULL REFERENCES source_plugins(id),
  external_id text NOT NULL, source_key text NOT NULL,
  current_context_revision integer, title text NOT NULL CHECK (length(title) <= 500),
  created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (source_plugin_id, external_id)
);
CREATE TABLE task_contexts (
  task_id uuid NOT NULL REFERENCES tasks(id), revision integer NOT NULL CHECK (revision > 0),
  schema_version text NOT NULL, context jsonb NOT NULL,
  sha256 text NOT NULL CHECK (sha256 ~ '^[a-f0-9]{64}$'),
  source_revision text, created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (task_id, revision)
);
ALTER TABLE tasks ADD CONSTRAINT current_context_fk
  FOREIGN KEY (id, current_context_revision) REFERENCES task_contexts(task_id, revision)
  DEFERRABLE INITIALLY DEFERRED;
CREATE TABLE agent_profiles (
  id uuid NOT NULL, revision integer NOT NULL CHECK (revision > 0),
  workspace_id uuid NOT NULL REFERENCES workspaces(id), name text NOT NULL, role text NOT NULL,
  schema_version text NOT NULL, profile jsonb NOT NULL, sha256 text NOT NULL CHECK (sha256 ~ '^[a-f0-9]{64}$'),
  created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (id, revision),
  UNIQUE (workspace_id, name, revision)
);
CREATE TABLE workflow_runs (
  id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id),
  task_id uuid NOT NULL, context_revision integer NOT NULL,
  repository_id uuid NOT NULL REFERENCES repositories(id), base_sha text NOT NULL,
  workflow_id text NOT NULL UNIQUE, temporal_execution_id text,
  state text NOT NULL CHECK (state IN ('QUEUED','CONTEXT_REVIEW','AWAITING_CONTEXT','PLANNING','AWAITING_PLAN','IMPLEMENTING','TESTING','REVIEWING','AWAITING_FINAL','NEEDS_ATTENTION','REPORT_PENDING','COMPLETED','FAILED','CANCELLING','CANCELLED')),
  state_revision bigint NOT NULL DEFAULT 0 CHECK (state_revision >= 0),
  manifest jsonb NOT NULL, manifest_sha256 text NOT NULL CHECK (manifest_sha256 ~ '^[a-f0-9]{64}$'),
  budgets jsonb NOT NULL, counters jsonb NOT NULL DEFAULT '{}',
  created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, ended_at timestamptz,
  FOREIGN KEY (task_id, context_revision) REFERENCES task_contexts(task_id, revision)
);
CREATE UNIQUE INDEX one_active_run_per_task ON workflow_runs(task_id)
  WHERE state NOT IN ('COMPLETED','FAILED','CANCELLED');
CREATE INDEX workflow_runs_listing ON workflow_runs(workspace_id, created_at DESC, id);
CREATE TABLE artifacts (
  id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id),
  run_id uuid REFERENCES workflow_runs(id), kind text NOT NULL,
  sha256 text NOT NULL CHECK (sha256 ~ '^[a-f0-9]{64}$'),
  media_type text NOT NULL, size_bytes bigint NOT NULL CHECK (size_bytes >= 0),
  storage_locator text NOT NULL, sensitivity text NOT NULL CHECK (sensitivity IN ('normal','restricted','raw-log')),
  created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz, deleted_at timestamptz
);
CREATE INDEX artifacts_retention ON artifacts(expires_at) WHERE deleted_at IS NULL;
CREATE TABLE agent_steps (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES workflow_runs(id),
  role text NOT NULL, logical_iteration integer NOT NULL CHECK (logical_iteration > 0),
  profile_id uuid NOT NULL, profile_revision integer NOT NULL,
  prompt_artifact_id uuid REFERENCES artifacts(id), state text NOT NULL,
  started_at timestamptz, ended_at timestamptz, duration_ms bigint CHECK (duration_ms >= 0),
  outcome text, FOREIGN KEY (profile_id, profile_revision) REFERENCES agent_profiles(id, revision),
  UNIQUE (run_id, role, logical_iteration)
);
CREATE TABLE pricing_snapshots (
  id uuid PRIMARY KEY, provider text NOT NULL, resolved_model text NOT NULL,
  currency text NOT NULL CHECK (currency = 'USD'), effective_at timestamptz NOT NULL,
  rates jsonb NOT NULL, source_url text, sha256 text NOT NULL UNIQUE CHECK (sha256 ~ '^[a-f0-9]{64}$'),
  captured_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE model_usage (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES workflow_runs(id),
  step_id uuid NOT NULL REFERENCES agent_steps(id), operation_id text NOT NULL UNIQUE,
  attempt integer NOT NULL CHECK (attempt > 0), provider text NOT NULL,
  requested_model text NOT NULL, resolved_model text, provider_request_id text,
  input_tokens bigint CHECK (input_tokens >= 0), output_tokens bigint CHECK (output_tokens >= 0),
  cached_read_tokens bigint CHECK (cached_read_tokens >= 0), cache_write_tokens bigint CHECK (cache_write_tokens >= 0),
  reasoning_tokens bigint CHECK (reasoning_tokens >= 0),
  usage_status text NOT NULL CHECK (usage_status IN ('FINAL','PARTIAL','UNKNOWN')),
  pricing_status text NOT NULL CHECK (pricing_status IN ('PRICED','UNPRICED')),
  pricing_snapshot_id uuid REFERENCES pricing_snapshots(id), estimated_cost_usd numeric(20,9) CHECK (estimated_cost_usd >= 0),
  billable_categories jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(),
  CHECK (pricing_status <> 'UNPRICED' OR estimated_cost_usd IS NULL)
);
CREATE INDEX model_usage_run ON model_usage(run_id, created_at);
CREATE TABLE usage_adjustments (
  id uuid PRIMARY KEY, usage_id uuid NOT NULL REFERENCES model_usage(id),
  reconciliation_key text NOT NULL UNIQUE, replacement_facts jsonb NOT NULL,
  reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE tool_calls (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES workflow_runs(id),
  step_id uuid NOT NULL REFERENCES agent_steps(id), operation_id text NOT NULL UNIQUE,
  tool_name text NOT NULL, arguments_sha256 text NOT NULL, policy_result text NOT NULL,
  state text NOT NULL, exit_code integer, started_at timestamptz NOT NULL, ended_at timestamptz,
  duration_ms bigint CHECK (duration_ms >= 0), artifact_ids jsonb NOT NULL DEFAULT '[]'
);
CREATE INDEX tool_calls_run ON tool_calls(run_id, started_at);
CREATE TABLE retry_attempts (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES workflow_runs(id),
  step_id uuid REFERENCES agent_steps(id), operation_id text NOT NULL,
  loop_kind text NOT NULL CHECK (loop_kind IN ('transport','test-repair','review-repair','schema-repair','human-replan')),
  iteration integer NOT NULL CHECK (iteration > 0), attempt_limit integer NOT NULL CHECK (attempt_limit > 0),
  cause_class text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (operation_id, loop_kind, iteration)
);
CREATE TABLE decision_gates (
  id uuid NOT NULL, version integer NOT NULL CHECK (version > 0),
  run_id uuid NOT NULL REFERENCES workflow_runs(id),
  kind text NOT NULL CHECK (kind IN ('CLARIFICATION','PLAN_APPROVAL','FINAL_APPROVAL','RECOVERY')),
  state text NOT NULL CHECK (state IN ('PENDING','DECIDED','SUPERSEDED','CANCELLED')),
  proposal jsonb NOT NULL, artifact_hashes jsonb NOT NULL,
  opened_at timestamptz NOT NULL, closed_at timestamptz,
  PRIMARY KEY (id, version), UNIQUE (id, version, run_id)
);
CREATE UNIQUE INDEX one_pending_gate_per_run ON decision_gates(run_id) WHERE state = 'PENDING';
CREATE TABLE gate_decisions (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES workflow_runs(id),
  gate_id uuid NOT NULL, gate_version integer NOT NULL,
  idempotency_key uuid NOT NULL UNIQUE, payload_sha256 text NOT NULL,
  decision text NOT NULL CHECK (decision IN ('APPROVE','REJECT')),
  reason text, actor_id uuid NOT NULL, recorded_at timestamptz NOT NULL,
  UNIQUE (gate_id, gate_version),
  FOREIGN KEY (gate_id, gate_version, run_id) REFERENCES decision_gates(id, version, run_id),
  CHECK ((decision = 'REJECT' AND reason IS NOT NULL AND reason ~ '[^[:space:]]' AND length(reason) BETWEEN 1 AND 8000)
    OR (decision = 'APPROVE' AND reason IS NULL))
);
CREATE TABLE gate_artifacts (
  gate_id uuid NOT NULL, gate_version integer NOT NULL, artifact_id uuid NOT NULL REFERENCES artifacts(id),
  FOREIGN KEY (gate_id, gate_version) REFERENCES decision_gates(id, version),
  PRIMARY KEY (gate_id, gate_version, artifact_id)
);
CREATE TABLE state_checkpoints (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES workflow_runs(id),
  state_revision bigint NOT NULL CHECK (state_revision >= 0),
  workflow_id text NOT NULL, temporal_execution_id text NOT NULL,
  manifest_sha256 text NOT NULL, snapshot jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (run_id, state_revision)
);
CREATE TABLE workspace_event_counters (
  workspace_id uuid PRIMARY KEY REFERENCES workspaces(id), last_seq bigint NOT NULL DEFAULT 0 CHECK (last_seq >= 0)
);
CREATE TABLE outbox_events (
  workspace_id uuid NOT NULL REFERENCES workspaces(id), seq bigint NOT NULL CHECK (seq > 0),
  event_id uuid NOT NULL UNIQUE, run_id uuid REFERENCES workflow_runs(id),
  state_revision bigint, event_type text NOT NULL, schema_version text NOT NULL,
  payload jsonb NOT NULL, occurred_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (workspace_id, seq)
);
CREATE INDEX outbox_retention ON outbox_events(created_at);
CREATE TABLE telemetry_logs (
  id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id),
  run_id uuid NOT NULL REFERENCES workflow_runs(id), step_id uuid REFERENCES agent_steps(id),
  attempt_id uuid, operation_id text, event_seq bigint NOT NULL,
  kind text NOT NULL, severity text NOT NULL CHECK (severity IN ('DEBUG','INFO','WARN','ERROR')),
  measurements jsonb NOT NULL DEFAULT '{}', attributes jsonb NOT NULL DEFAULT '{}',
  redacted_payload jsonb NOT NULL, occurred_at timestamptz NOT NULL
  -- No FK to outbox: journal retention is shorter than retained audit/usage data.
);
CREATE INDEX telemetry_logs_run ON telemetry_logs(run_id, occurred_at, id);
CREATE INDEX telemetry_logs_retention ON telemetry_logs(occurred_at);
CREATE TABLE secrets_metadata (
  id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id),
  vault_ref text NOT NULL UNIQUE CHECK (vault_ref LIKE 'vault://%'),
  scope text NOT NULL, label text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), rotated_at timestamptz
);
CREATE TABLE external_operations (
  id uuid PRIMARY KEY, run_id uuid NOT NULL REFERENCES workflow_runs(id),
  source_plugin_id uuid NOT NULL REFERENCES source_plugins(id), operation_key text NOT NULL UNIQUE,
  kind text NOT NULL CHECK (kind IN ('comment','status')),
  request_sha256 text NOT NULL, state text NOT NULL CHECK (state IN ('INTENT','IN_FLIGHT','APPLIED','UNCERTAIN','FAILED')),
  receipt jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE ingest_deliveries (
  source_plugin_id uuid NOT NULL REFERENCES source_plugins(id), delivery_id text NOT NULL,
  payload_sha256 text NOT NULL, task_id uuid REFERENCES tasks(id), received_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (source_plugin_id, delivery_id)
);
CREATE TABLE command_requests (
  id uuid PRIMARY KEY, workspace_id uuid NOT NULL REFERENCES workspaces(id),
  idempotency_key uuid NOT NULL UNIQUE, payload_sha256 text NOT NULL,
  command_type text NOT NULL, payload jsonb NOT NULL,
  state text NOT NULL CHECK (state IN ('PENDING','DISPATCHED','COMPLETED','FAILED')),
  result jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now()
);

-- Event append algorithm, executed in each product transaction:
-- UPDATE workspace_event_counters SET last_seq = last_seq + 1
-- WHERE workspace_id = $1 RETURNING last_seq;
-- INSERT outbox_events using that value, then COMMIT. Never use nextval() for commit order.
-- Application roles receive INSERT/SELECT on immutable ledgers; maintenance owns retention DELETE.
-- Deny UPDATE on task_contexts, agent_profiles, pricing_snapshots, model_usage,
-- usage_adjustments, gate_decisions, state_checkpoints and outbox_events.
COMMIT;
